using ProjetoIntegradorBack.Domain.Enums; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Domain.Models; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class RelatorioRepository(ProjetoIntegradorBackDbContext context):IRelatorioRepository{
public async Task<Result<IReadOnlyList<ComissaoEmployeeInfo>>> GetCommissionsPorMonthAsync(Guid establishmentId,int month,int year,Guid? employeeId,CancellationToken ct=default){try{var q=context.Appointments.Include(x=>x.Employee).Where(x=>x.EstablishmentId==establishmentId&&x.Status==StatusAppointment.Concluido&&x.DateTime.Month==month&&x.DateTime.Year==year);if(employeeId.HasValue)q=q.Where(x=>x.EmployeeId==employeeId);var a=await q.ToListAsync(ct);var r=a.GroupBy(x=>x.EmployeeId).Select(g=>new ComissaoEmployeeInfo{EmployeeId=g.Key,NameEmployee=g.First().Employee.Name,Role=g.First().Employee.Role,CommissionPercentage=g.First().Employee.CommissionPercentage,TotalAtendimentos=g.Count(),FaturamentoBruto=g.Sum(x=>x.TotalAmount),ValorComissao=g.Sum(x=>x.TotalAmount)*g.First().Employee.CommissionPercentage/100}).ToList();return Result<IReadOnlyList<ComissaoEmployeeInfo>>.AsSuccess(r);}catch(Exception ex){return Result<IReadOnlyList<ComissaoEmployeeInfo>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<ResumoAtendimentosInfo>> GetResumoAtendimentosAsync(Guid id,DateTime start,DateTime end,CancellationToken ct=default){try{var a=await context.Appointments.Where(x=>x.EstablishmentId==id&&x.DateTime>=start&&x.DateTime<=end).ToListAsync(ct);return Result<ResumoAtendimentosInfo>.AsSuccess(new ResumoAtendimentosInfo{TotalAppointments=a.Count,Confirmados=a.Count(x=>x.Status==StatusAppointment.Confirmado),Concluidos=a.Count(x=>x.Status==StatusAppointment.Concluido),Cancelados=a.Count(x=>x.Status==StatusAppointment.Cancelado),FaturamentoTotal=a.Where(x=>x.Status==StatusAppointment.Concluido).Sum(x=>x.TotalAmount)});}catch(Exception ex){return Result<ResumoAtendimentosInfo>.AsFailure(new Failure(500,ex.Message));}}}